* { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --teal: #31777A;
  --teal-soft: #e3efef;
  --teal-light: #a9d2d3;
  --ink: #14181d;
  --paper: #fdfbf5;
  --line: #e6e0d0;
  --muted: #6f6a5c;
  --blue: #1450a3;
  --red: #d64a2e;
  --ok: #1e7a4d;
  --card: #ffffff;
}

body {
  font-family: 'Inter', -apple-system, sans-serif;
  background: var(--paper);
  color: var(--ink);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

.disp { font-family: 'Archivo', sans-serif; }
.mono { font-family: 'JetBrains Mono', monospace; }
.wrap { max-width: 1080px; margin: 0 auto; padding: 0 24px; }

/* Header */
header { background: var(--paper); border-bottom: 3px solid var(--ink); position: sticky; top: 0; z-index: 20; }
.nav { display: flex; align-items: center; justify-content: space-between; padding: 15px 0; }
.logo { font-family: 'Archivo', sans-serif; font-weight: 900; font-size: 20px; color: var(--ink); text-decoration: none; letter-spacing: -.02em; display: flex; align-items: center; gap: 9px; }
.logo .mark { background: var(--teal); border: 2.5px solid var(--ink); border-radius: 8px; width: 34px; height: 34px; display: flex; align-items: center; justify-content: center; }
.nav .links { display: flex; align-items: center; }
.nav .links a { color: var(--ink); text-decoration: none; font-size: 14.5px; font-weight: 600; margin-left: 24px; }
.nav .links a.btn.inv { color: #fff; }

/* Buttons */
.btn { display: inline-block; font-family: 'Archivo', sans-serif; background: var(--ink); color: #fff; padding: 14px 26px; border-radius: 10px; font-weight: 800; font-size: 15px; text-decoration: none; border: 2.5px solid var(--ink); transition: all .12s; cursor: pointer; }
.btn:hover { transform: translate(-2px,-2px); box-shadow: 4px 4px 0 var(--teal); }
.btn.inv { background: var(--teal); color: #fff; }
.btn.inv:hover { box-shadow: 4px 4px 0 var(--ink); }

/* Hero */
.hero { padding: 64px 0 46px; text-align: center; }
.stamp { display: inline-flex; align-items: center; gap: 8px; background: var(--card); border: 2px solid var(--ink); border-radius: 30px; padding: 8px 18px; font-weight: 700; font-size: 13px; margin-bottom: 26px; }
.stamp .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--ok); animation: pulse 2s infinite; }
@keyframes pulse { 0%,100% { opacity: 1 } 50% { opacity: .35 } }
h1 { font-family: 'Archivo', sans-serif; font-size: 50px; line-height: 1.05; font-weight: 900; letter-spacing: -.025em; max-width: 830px; margin: 0 auto; }
h1 .hl { background: linear-gradient(transparent 62%, var(--teal-light) 62%); padding: 0 4px; }
.sub { font-size: 18px; color: #4a4a42; max-width: 640px; margin: 22px auto 30px; }
.cta-row { display: flex; gap: 14px; justify-content: center; margin-bottom: 14px; }
.small-note { font-size: 13px; color: #8a8578; }
.proof { display: flex; justify-content: center; gap: 48px; margin: 44px auto 0; padding-top: 28px; border-top: 1.5px solid var(--line); max-width: 860px; }
.proof .n { font-family: 'Archivo', sans-serif; font-size: 32px; font-weight: 900; color: var(--ink); }
.proof .n.accent { color: var(--red); }
.proof .l { font-size: 12.5px; color: var(--muted); margin-top: 2px; max-width: 150px; }

/* Story */
.story { padding: 50px 0; }
.story-grid { display: grid; grid-template-columns: repeat(3, 1fr); border: 2.5px solid var(--ink); border-radius: 16px; overflow: hidden; background: var(--card); }
.story-cell { padding: 30px 26px; border-right: 2.5px solid var(--ink); }
.story-cell:last-child { border-right: none; }
.story-cell .day { font-family: 'Archivo', sans-serif; font-weight: 900; font-size: 12.5px; color: var(--red); text-transform: uppercase; letter-spacing: .06em; margin-bottom: 10px; }
.story-cell h3 { font-family: 'Archivo', sans-serif; font-size: 19px; font-weight: 800; margin-bottom: 8px; line-height: 1.25; }
.story-cell p { font-size: 14px; color: #55524a; }
.story-cell.mid { background: var(--teal-soft); }

/* Feed */
.feed-sec { padding: 30px 0 60px; }
h2.disp { font-size: 34px; font-weight: 900; letter-spacing: -.02em; text-align: center; margin-bottom: 10px; font-family: 'Archivo', sans-serif; }
.center-sub { text-align: center; color: #55524a; max-width: 600px; margin: 0 auto 34px; }
.feed { max-width: 780px; margin: 0 auto; border: 2.5px solid var(--ink); border-radius: 14px; overflow: hidden; background: var(--card); box-shadow: 8px 8px 0 var(--teal); }
.feed-head { display: flex; justify-content: space-between; align-items: center; padding: 13px 20px; background: var(--teal-soft); border-bottom: 2px solid var(--ink); font-size: 13px; }
.feed-head .live { display: inline-flex; align-items: center; gap: 7px; font-weight: 700; color: var(--ok); }
.feed-head .dot { width: 7px; height: 7px; border-radius: 50%; background: var(--ok); animation: pulse 2s infinite; }
.row { display: grid; grid-template-columns: 96px 1fr auto; gap: 16px; padding: 15px 20px; border-bottom: 1.5px dashed var(--line); align-items: center; }
.row:last-of-type { border-bottom: none; }
.row:hover { background: #f4faf9; }
.row .date { font-size: 12px; color: var(--muted); font-family: 'JetBrains Mono', monospace; }
.row .what { font-size: 14.5px; }
.row .what .meta { font-size: 12.5px; color: var(--muted); margin-top: 2px; }
.tag { font-size: 11.5px; font-weight: 700; padding: 4px 10px; border-radius: 20px; background: var(--teal-soft); border: 1.5px solid var(--ink); white-space: nowrap; }
.blurred { filter: blur(5px); user-select: none; pointer-events: none; }
.feed-foot { padding: 13px 20px; text-align: center; font-size: 13.5px; background: var(--teal-soft); border-top: 2px solid var(--ink); }
.feed-foot a { color: var(--red); font-weight: 700; text-decoration: none; }
.verify { text-align: center; margin-top: 18px; font-size: 12.5px; color: var(--muted); max-width: 640px; margin-left: auto; margin-right: auto; }

/* Dark proof */
.proof-sec { background: var(--ink); color: var(--paper); padding: 58px 0; }
.proof-sec h2 { color: #fff; }
.nums { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 34px; }
.num-card { border: 2px solid #333b44; border-radius: 14px; padding: 24px; text-align: center; }
.num-card .n { font-family: 'Archivo', sans-serif; font-size: 32px; font-weight: 900; color: var(--teal-light); }
.num-card .l { font-size: 13px; color: #a8b0b8; margin-top: 4px; }

/* Pricing */
.pricing { padding: 62px 0 70px; }
.plans { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 38px; }
.plan { border: 2.5px solid var(--ink); border-radius: 16px; padding: 30px 26px; background: var(--card); position: relative; transition: transform .12s; display: flex; flex-direction: column; }
.plan:hover { transform: translateY(-4px); }
.plan.mid { background: var(--teal-soft); box-shadow: 8px 8px 0 var(--teal); }
.plan .tag2 { position: absolute; top: -14px; right: 20px; background: var(--red); color: #fff; font-family: 'Archivo', sans-serif; font-weight: 800; font-size: 12px; padding: 5px 14px; border-radius: 20px; border: 2px solid var(--ink); transform: rotate(2deg); }
.plan h3 { font-family: 'Archivo', sans-serif; font-size: 16px; font-weight: 900; text-transform: uppercase; letter-spacing: .03em; }
.plan .price { font-family: 'Archivo', sans-serif; font-size: 46px; font-weight: 900; margin: 12px 0 0; }
.plan .price small { font-size: 15px; color: var(--muted); font-weight: 600; }
.plan .vol { font-family: 'JetBrains Mono', monospace; font-size: 12px; font-weight: 600; color: var(--ok); margin: 8px 0 16px; }
.plan ul { list-style: none; margin: 0 0 24px; flex: 1; }
.plan li { padding: 7px 0 7px 28px; font-size: 14px; position: relative; }
.plan li::before { content: '✓'; position: absolute; left: 2px; font-weight: 900; color: var(--blue); }
.plan .btn { width: 100%; text-align: center; }
.engage { text-align: center; margin-top: 26px; font-size: 14px; color: #55524a; }
.engage b { background: linear-gradient(transparent 62%, var(--teal-light) 62%); }

footer { border-top: 3px solid var(--ink); padding: 26px 0; font-size: 13px; color: var(--muted); }
footer .wrap { display: flex; justify-content: space-between; }

@media (max-width: 880px) {
  h1 { font-size: 33px; }
  .story-grid, .plans, .nums { grid-template-columns: 1fr; }
  .story-cell { border-right: none; border-bottom: 2.5px solid var(--ink); }
  .story-cell:last-child { border-bottom: none; }
  .proof { flex-wrap: wrap; gap: 24px; }
  .cta-row { flex-direction: column; align-items: center; }
  .row { grid-template-columns: 1fr auto; }
  .row .date { display: none; }
  footer .wrap { flex-direction: column; gap: 6px; }
}
